<?php require_once __DIR__.'/../includes/permissions.php';require_login();$u=current_user();$pdo=db();if($_SERVER['REQUEST_METHOD']==='GET'){require_permission('appointments.view');$sql='SELECT a.reference_no,a.appointment_date,a.appointment_time,a.status,s.name service_name,r.patient_id FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN residents r ON r.id=a.resident_id WHERE 1';$p=[];if($u['role_name']!=='System Administrator'){$sql.=' AND (a.assigned_staff_id=? OR a.assigned_staff_id IS NULL)';$p[]=$u['id'];}$sql.=' ORDER BY a.appointment_date DESC,a.appointment_time LIMIT 300';$q=$pdo->prepare($sql);$q->execute($p);json_response(['success'=>true,'data'=>$q->fetchAll()]);}if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('appointments.create');$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$sid=(int)($d['service_id']??0);$date=(string)($d['appointment_date']??'');$q=$pdo->prepare('SELECT daily_capacity FROM services WHERE id=? AND status="Active"');$q->execute([$sid]);$cap=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE service_id=? AND appointment_date=? AND status IN ("Pending","Scheduled")');$q->execute([$sid,$date]);if(!$cap||$q->fetchColumn()>=$cap)json_response(['success'=>false,'message'=>'Service unavailable or capacity full'],422);$ref='APT-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$q=$pdo->prepare('INSERT INTO appointments(reference_no,resident_id,service_id,appointment_date,appointment_time,assigned_staff_id,purpose,status,created_by) VALUES(?,?,?,?,?,?,?,"Scheduled",?)');$q->execute([$ref,(int)$d['resident_id'],$sid,$date,$d['appointment_time'],$d['assigned_staff_id']??null,$d['purpose']??null,$u['id']]);json_response(['success'=>true,'reference_no'=>$ref],201);}json_response(['success'=>false,'message'=>'Unsupported request'],405);
